1	import { useEffect } from "react";
2	import { FOCUS_TOKEN_EXPIRY_BUFFER_MS, hasStoredToken, isTokenExpired } from "@/auth-state";
3	
4	/**
5	 * Hook that proactively refreshes the access token when the tab becomes visible
6	 * and the token is expired or expiring soon.
7	 *
8	 * This prevents React Query's automatic refetch-on-window-focus from triggering
9	 * multiple 401 errors when the user returns to the tab after the token has expired.
10	 *
11	 * Related issue: https://github.com/usememos/memos/issues/5589
12	 */
13	export function useTokenRefreshOnFocus(refreshFn: () => Promise<void>, enabled: boolean = true) {
14	  useEffect(() => {
15	    if (!enabled) return;
16	
17	    const handleVisibilityChange = async () => {
18	      // Only act when tab becomes visible
19	      if (document.visibilityState !== "visible") {
20	        return;
21	      }
22	
23	      // Only refresh if the user has logged in before (token in localStorage)
24	      if (!hasStoredToken()) {
25	        return;
26	      }
27	
28	      // Check if token is expired or expiring soon (within 2 minutes)
29	      // Use a longer buffer than normal requests to be proactive
30	      if (isTokenExpired(FOCUS_TOKEN_EXPIRY_BUFFER_MS)) {
31	        try {
32	          console.debug("[useTokenRefreshOnFocus] Token expired/expiring, refreshing before queries refetch");
33	          await refreshFn();
34	          console.debug("[useTokenRefreshOnFocus] Token refreshed successfully");
35	        } catch (error) {
36	          // Don't block - let the normal auth interceptor handle it
37	          // The user will be redirected if refresh fails
38	          console.error("[useTokenRefreshOnFocus] Failed to refresh token:", error);
39	        }
40	      }
41	    };
42	
43	    document.addEventListener("visibilitychange", handleVisibilityChange);
44	
45	    return () => {
46	      document.removeEventListener("visibilitychange", handleVisibilityChange);
47	    };
48	  }, [refreshFn, enabled]);
49	}
